window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["deployment"]={"title":"AI 部署：把离线能力变成可容量化、可灰度、可回滚的服务","subtitle":"从运行位置、排队与批处理，到版本发布、幂等副作用、降级和事故响应。","thesis":"部署不是把模型包成 URL，而是把模型、提示、索引、工具、策略和基础设施组成一个<b>可追溯发布单元</b>。可靠性取决于容量与尾延迟、真实副作用边界、渐进放量和完整回滚；离线质量更高并不足以证明生产上更好。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"准确率 +3 点、吞吐减半、p95 翻倍","rule":"若门槛是任务≥87%、越权≤0.5%、p95≤1.8s、峰值容量≥16 req/s","steps":"ceil(24/17)=2","interpretation":"优化后才进入金丝雀"}}],"formulas":[{"id":"deployment-capacity","section":3,"formulaIndex":1,"symbols":[{"name":"ρ","meaning":"请求系统的资源利用率","evidence":"输出利用率 ρ"},{"name":"λ","meaning":"单位时间到达的请求数量","evidence":"到达率 λ"},{"name":"S","meaning":"一个请求平均占用服务资源的时间","evidence":"平均服务时间 S"},{"name":"c","meaning":"能够同时服务请求的并行槽位数","evidence":"并行槽位 c"},{"name":"Lsystem","meaning":"系统内正在服务或排队的平均请求数","evidence":"系统内平均请求数 Lsystem"},{"name":"W","meaning":"请求从进入到完成的端到端平均时间","evidence":"端到端平均时间 W"}]},{"id":"deployment-release-unit","section":7,"formulaIndex":1,"symbols":[{"name":"ReleaseUnit","meaning":"必须作为一个整体追踪和回滚的发布单元","evidence":"输出一个 releaseId 与兼容矩阵"},{"name":"Model","meaning":"发布使用的模型版本","evidence":"输入模型、提示、解码"},{"name":"Prompt","meaning":"发布使用的提示版本","evidence":"输入模型、提示、解码"},{"name":"Decode","meaning":"生成时使用的解码配置","evidence":"输入模型、提示、解码"},{"name":"Index","meaning":"检索使用的索引版本","evidence":"索引用蓝绿别名"},{"name":"ToolSchema","meaning":"工具输入输出的接口契约版本","evidence":"工具 schema"},{"name":"Policy","meaning":"权限与安全策略版本","evidence":"策略、代码和基础设施配置"},{"name":"Code","meaning":"编排和服务代码版本","evidence":"策略、代码和基础设施配置"},{"name":"Infra","meaning":"承载服务的基础设施配置版本","evidence":"基础设施配置"}]}],"termReviews":[{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"continuous batching","meaning":"运行中持续把新请求加入当前批次的调度方式","purpose":"提高不同长度生成请求共享硬件的吞吐","definitionEvidence":"continuous batching 提升吞吐但让调度复杂","purposeEvidence":"提高吞吐"}]},{"section":7,"reviewedAt":"2026-07-27","terms":[{"name":"幂等键","meaning":"让相同业务动作的重复请求只生效一次的稳定标识","purpose":"防止超时重试造成重复退款等副作用","definitionEvidence":"重试不重复退款","purposeEvidence":"使用幂等键"},{"name":"expand/contract","meaning":"先扩展兼容结构、迁移后再删除旧结构的 schema 变更流程","purpose":"使新旧代码在发布与回滚期间都能读写","definitionEvidence":"先让新旧代码都能读写","purposeEvidence":"再迁移，最后删除旧字段"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"运行位置决定托管、自托管、端侧或混合方案及责任边界。","evidence":"输出托管 API、自托管、端侧或混合方案"},"problem":{"answer":"它解决数据、延迟、弹性、成本和运维责任如何取舍。","evidence":"选择必须基于实际流量、隐私、可用性和团队责任"},"inputOutput":{"answer":"输入流量地域隐私硬件和团队能力，输出运行方案。","evidence":"输入流量、数据地域、隐私、延迟、可用性、硬件和团队运维能力"},"mechanism":{"answer":"逐项比较方案获得的控制与必须承担的运维。","evidence":"每种位置交换的是控制权、弹性、成本和责任"},"interpretation":{"answer":"选择表示约束下的责任分配，不表示某方案天然更快。","evidence":"端侧不自动低延迟，自托管也不自动便宜"},"boundary":{"answer":"没有补丁值班灾备能力时不应只为控制偏好自托管。","evidence":"不能只因偏好数据控制就自托管"}},{"section":2,"definition":{"answer":"服务路径是请求跨认证排队检索模型工具和传输的完整链路。","evidence":"服务路径输入一次请求及其认证、排队、检索"},"problem":{"answer":"它解释模型计算很快而用户仍等待两秒的原因。","evidence":"关键路径上的排队或工具可以主导 2s"},"inputOutput":{"answer":"输入一次请求及所有阶段，输出端到端延迟状态和副作用。","evidence":"输出端到端延迟、状态与副作用"},"mechanism":{"answer":"沿关键路径串联阶段并追踪所有发布依赖。","evidence":"发布单元必须覆盖全部依赖"},"interpretation":{"answer":"单个模型耗时不能代表用户端到端体验。","evidence":"模型耗时 600ms 只是其中一段"},"boundary":{"answer":"外部动作必须另有权限幂等和补偿设计。","evidence":"外部副作用需要权限、幂等与补偿"}},{"section":3,"definition":{"answer":"容量账用利用率和 Little 定律描述服务拥塞。","evidence":"输出利用率 ρ 与系统内平均请求数 Lsystem"},"problem":{"answer":"它初步判断到达率和服务能力是否会导致排队。","evidence":"ρ=0.8 已会排队"},"inputOutput":{"answer":"输入 λ、S、c、W，输出 ρ 和 Lsystem。","evidence":"输入到达率 λ、平均服务时间 S、并行槽位 c 和端到端平均时间 W"},"mechanism":{"answer":"计算 ρ=λ×S/c 与 Lsystem=λ×W。","evidence":"ρ=λ×S/c，Lsystem=λ×W"},"interpretation":{"answer":"ρ 接近一表示尾延迟会非线性恶化。","evidence":"接近 1 时尾延迟非线性恶化"},"boundary":{"answer":"LLM 长度批处理工具和突发仍需真实压力测试。","evidence":"仍需压力测试"}},{"section":4,"definition":{"answer":"发布门禁把质量安全延迟吞吐和成本共同用于上线决策。","evidence":"输出是否满足全部门槛及所需实例数 nInstance"},"problem":{"answer":"它防止只因离线准确率提高就直接发布慢服务。","evidence":"质量更高却不能直接上线"},"inputOutput":{"answer":"输入两个版本的多项指标，输出门禁结论和容量数量。","evidence":"输入 v41 与 v42 的任务通过率、越权率、p95、吞吐和单位成功成本"},"mechanism":{"answer":"逐项过门槛，再用峰值吞吐除以实例能力并向上取整。","evidence":"24/17 得至少 2 个实例"},"interpretation":{"answer":"两实例是无冗余下限，实际故障余量可能要求三个。","evidence":"实际需求提高到 3"},"boundary":{"answer":"不能使用平均利用率替代峰值和故障容量评估。","evidence":"不能按平均利用率裸配"}},{"section":5,"definition":{"answer":"批处理缓存量化裁剪和路由是改变不同瓶颈的优化。","evidence":"缓存复用计算，量化改变数值表示"},"problem":{"answer":"它区分看似都能变快的手段各自改了什么。","evidence":"批处理改变排队"},"inputOutput":{"answer":"输入瓶颈和各优化参数，输出性能资源质量与隔离差异。","evidence":"输出吞吐、首 token 延迟、显存、质量与隔离差异"},"mechanism":{"answer":"按瓶颈选手段并一次只改少量可追踪变量。","evidence":"一次只改少量变量并记录逐请求版本"},"interpretation":{"answer":"收益需与对应的排队泄漏精度或证据风险一起解释。","evidence":"裁剪改变可见证据，路由改变请求模型"},"boundary":{"answer":"多种优化同时上线会失去收益与退化归因。","evidence":"才能归因和回归"}},{"section":6,"definition":{"answer":"影子金丝雀蓝绿是观察不同发布风险的渐进策略。","evidence":"影子结果不影响用户且禁止不可逆动作"},"problem":{"answer":"它们控制候选版本影响真实用户和副作用的范围。","evidence":"金丝雀产生真实结果，蓝绿保留两套完整环境"},"inputOutput":{"answer":"输入版本流量副作用窗口和回滚能力，输出发布动作。","evidence":"输入候选版本、真实流量、副作用风险、观察窗口和回滚能力"},"mechanism":{"answer":"影子不生效、金丝雀小流量生效、蓝绿保留双环境。","evidence":"发布策略输入候选版本、真实流量、副作用风险"},"interpretation":{"answer":"通过表示对应观察窗口未越线，不保证绝对安全。","evidence":"策略选择取决于要观察的风险"},"boundary":{"answer":"副作用需幂等补偿，分流需保持用户或会话稳定。","evidence":"按用户或会话稳定分流"}},{"section":7,"definition":{"answer":"原子发布把模型提示索引工具策略代码和配置组成发布单元。","evidence":"输入模型、提示、解码、索引、工具 schema、策略、代码和基础设施配置"},"problem":{"answer":"它避免只退模型却留下不兼容提示缓存或业务状态。","evidence":"单退模型会留下新提示、缓存或状态"},"inputOutput":{"answer":"输入全部组件版本，输出 releaseId 与兼容矩阵。","evidence":"输出一个 releaseId 与兼容矩阵"},"mechanism":{"answer":"按 releaseId 同步恢复可逆组件并对状态使用兼容迁移。","evidence":"回滚按 releaseId 同步恢复可逆组件"},"interpretation":{"answer":"回滚成功表示组合恢复兼容，不代表外部副作用消失。","evidence":"不可逆副作用只能补偿"},"boundary":{"answer":"不可逆动作必须补偿，不能宣称通过版本回滚撤销。","evidence":"不能假装已经回滚"}},{"section":8,"definition":{"answer":"安全降级是在容量不足时按风险选择有限服务动作。","evidence":"输出排队、拒绝、延迟、小模型、截短或停服动作"},"problem":{"answer":"它在拥塞时保护关键路径又不绕过高风险验证。","evidence":"高权限退款不得因拥塞绕过验证"},"inputOutput":{"answer":"输入容量风险价值可逆性和依赖状态，输出降级动作。","evidence":"输入容量、风险等级、任务价值、可逆性和当前依赖状态"},"mechanism":{"answer":"低风险可延迟切模型，高风险失败关闭并标记结果。","evidence":"低风险任务可延迟或切换模型"},"interpretation":{"answer":"降级结果表示能力受限，必须被监控而非伪装正常。","evidence":"显式标记并监控"},"boundary":{"answer":"超时任务可能仍执行，重试需预算条件与同一幂等键。","evidence":"重试必须有可恢复条件、总预算和同一幂等键"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>比较云端、自托管和端侧约束；手算容量与排队风险；设计影子/金丝雀/蓝绿发布；定义降级、回滚和版本原子性。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>运行位置首先决定责任边界<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">同一个退款模型放在托管 API、自有 GPU 或客服电脑上，交换了什么？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>形态</th><th>获得</th><th>承担</th><th>适合</th></tr></thead><tbody><tr><td>托管 API</td><td>弹性、快速更新、免 GPU 运维</td><td>数据出域、配额、供应商与单价</td><td>快速迭代、波动流量</td></tr><tr><td>自托管云/机房</td><td>权重、数据、容量和版本控制</td><td>调度、补丁、安全与值班</td><td>稳定规模、强合规控制</td></tr><tr><td>边缘/端侧</td><td>离线、低网络往返、局部隐私</td><td>内存、功耗、硬件碎片与更新</td><td>弱网、实时、数据不出端</td></tr><tr><td>混合</td><td>端侧快路径与云端升级</td><td>同步、路由和一致性复杂度</td><td>分级风险与能力</td></tr></tbody></table></div><p>端侧不自动等于低延迟：设备算力不足时解码很慢；自托管不自动更便宜：低利用率、工程人力和冗余会吞掉单价优势。选择必须基于实际流量、隐私、可用性和团队责任。</p><p>运行位置选择输入流量、数据地域、隐私、延迟、可用性、硬件和团队运维能力，输出托管 API、自托管、端侧或混合方案。每种位置交换的是控制权、弹性、成本和责任；端侧不自动低延迟，自托管也不自动便宜。没有能力承担补丁、值班和灾备时，不能只因偏好数据控制就自托管。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>服务路径比模型权重更长<span class=\"dd-badge eng\">系统</span></h2><p class=\"dd-lead\">模型推理只花 600ms，为什么用户却等了 2 秒？</p><p>一次请求可能经历认证、限流、排队、上下文装配、检索、预填充、逐 token 解码、工具调用、后处理和流式传输。任一步都能主导尾延迟，工具副作用还要求幂等、权限与事务补偿。</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 720 250\" role=\"img\" aria-label=\"退款助手从网关、队列、检索、模型到工具的部署路径以及金丝雀回滚\"><defs><marker id=\"dp1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"16\" y=\"74\" width=\"96\" height=\"58\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"64\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">网关</text><text x=\"64\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">认证/限流</text><path d=\"M112,103 L148,103\" stroke=\"#6b7484\" marker-end=\"url(#dp1)\"/><rect x=\"150\" y=\"74\" width=\"96\" height=\"58\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"198\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">队列</text><text x=\"198\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">背压/批处理</text><path d=\"M246,103 L282,103\" stroke=\"#6b7484\" marker-end=\"url(#dp1)\"/><rect x=\"284\" y=\"74\" width=\"96\" height=\"58\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"332\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">检索</text><text x=\"332\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">index p17</text><path d=\"M380,103 L416,103\" stroke=\"#6b7484\" marker-end=\"url(#dp1)\"/><rect x=\"418\" y=\"74\" width=\"96\" height=\"58\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"466\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">模型 v42</text><text x=\"466\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">prompt h83</text><path d=\"M514,103 L550,103\" stroke=\"#6b7484\" marker-end=\"url(#dp1)\"/><rect x=\"552\" y=\"74\" width=\"144\" height=\"58\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"624\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">退款工具</text><text x=\"624\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">策略 s9 / 幂等键</text><path d=\"M466,133 C464,196 294,204 198,136\" fill=\"none\" stroke=\"#c77b72\" stroke-dasharray=\"5 4\" marker-end=\"url(#dp1)\"/><text x=\"362\" y=\"195\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">安全、质量或 p95 越线：停止放量，整体回滚到 v41 发布单元</text></svg><figcaption>图 1　可回滚对象不是单一权重，而是模型、提示、索引、工具 schema、策略与服务配置的组合版本。</figcaption></figure><p>服务路径输入一次请求及其认证、排队、检索、预填充、解码、工具和传输阶段，输出端到端延迟、状态与副作用。模型耗时 600ms 只是其中一段，关键路径上的排队或工具可以主导 2s；发布单元必须覆盖全部依赖。外部副作用需要权限、幂等与补偿，不能只回滚模型。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>吞吐、延迟与并发的基本账<span class=\"dd-badge math\">容量</span></h2><p class=\"dd-lead\">每秒来 8 个请求、平均服务 0.1 秒，单实例够不够？</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"利用率与 Little 定律\"><mi>ρ</mi><mo>=</mo><mfrac><mrow><mi>λ</mi><mo>×</mo><mi>S</mi></mrow><mi>c</mi></mfrac><mo>;</mo><mspace width=\"1em\"/><mi>Lsystem</mi><mo>=</mo><mi>λ</mi><mo>×</mo><mi>W</mi></math></div><p>若 c=1，λ=8/s，S=.1s，则 ρ=.8。即使平均服务时间只有 100ms，随机到达也会排队；接近 1 时尾延迟急剧上升。用 Little 定律 <code>L=λW</code>：若端到端平均 W=.5s，系统内平均约有 4 个请求。</p><p>LLM 还以 token 工作：输入长度决定 prefill，输出长度决定占槽时间，continuous batching 提升吞吐但让调度复杂。容量模型应按输入/输出长度、模型、优先级和工具路径切片，并用压力测试验证而非只套队列公式。</p><div class=\"dd-note warn\"><b>平均数不保 SLO。</b>　平均 500ms 可同时存在 p99=8s；容量评审必须看尾部、超时后的残留计算和突发流量。</div><p>容量估算输入到达率 λ、平均服务时间 S、并行槽位 c 和端到端平均时间 W，输出利用率 ρ 与系统内平均请求数 Lsystem。ρ=λ×S/c，Lsystem=λ×W；ρ=0.8 已会排队，接近 1 时尾延迟非线性恶化。公式只提供初步容量直觉，LLM 长度、批处理、工具和突发仍需压力测试。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：新模型为何质量更高却不能直接上线<span class=\"dd-badge math\">案例推演</span></h2><p class=\"dd-lead\">准确率 +3 点、吞吐减半、p95 翻倍时，怎样做发布决策？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>任务通过率</th><th>越权率</th><th>p95</th><th>吞吐</th><th>每成功任务成本</th></tr></thead><tbody><tr><td>v41</td><td>86%</td><td>0.4%</td><td>1.2s</td><td>20 req/s</td><td>¥0.10</td></tr><tr><td>v42 离线</td><td>89%</td><td>0.3%</td><td>—</td><td>—</td><td>—</td></tr><tr><td>v42 影子实测</td><td>88.5%</td><td>0.3%</td><td>2.6s</td><td>11 req/s</td><td>¥0.17</td></tr><tr><td>v42 优化后</td><td>88.3%</td><td>0.3%</td><td>1.5s</td><td>17 req/s</td><td>¥0.13</td></tr></tbody></table></div><p>若门槛是任务≥87%、越权≤0.5%、p95≤1.8s、峰值容量≥16 req/s，则 v42 原始服务形态失败，优化后才进入金丝雀。离线质量没有测排队、缓存、真实长度和工具超时，不能替代服务门禁。</p><p>峰值 24 req/s 时，即使优化实例额定 17 req/s，也至少要 <code>ceil(24/17)=2</code> 个实例；为单实例故障和突发留余量，可能需要 3 个。成本应按冗余后的实际利用率计算。</p><p>发布案例输入 v41 与 v42 的任务通过率、越权率、p95、吞吐和单位成功成本，输出是否满足全部门槛及所需实例数 nInstance。先检查任务≥87%、越权≤0.5%、p95≤1.8s、容量≥16 req/s，再用峰值到达率 λpeak 除以单实例额定吞吐 qinstance 并向上取整；24/17 得至少 2 个实例。冗余和单实例故障会把实际需求提高到 3，不能按平均利用率裸配。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>批处理、缓存和量化各在改什么<span class=\"dd-badge eng\">优化</span></h2><p class=\"dd-lead\">三个优化都能“变快”，为什么风险完全不同？</p><p>批处理提高硬件利用率，却增加等待和相互干扰；prompt/KV 缓存减少重复计算，但命中键必须包含模型、提示与权限上下文，避免跨用户泄漏；量化降低显存与带宽，可能改变少数切片质量。推测解码、裁剪上下文和小模型路由也各有准确性边界。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>优化</th><th>主要收益</th><th>必须回归</th></tr></thead><tbody><tr><td>连续批处理</td><td>吞吐/利用率</td><td>排队、长短请求公平、p99</td></tr><tr><td>前缀/KV 缓存</td><td>TTFT 与成本</td><td>版本键、租户隔离、失效</td></tr><tr><td>量化</td><td>显存、速度</td><td>关键切片、长上下文、校准</td></tr><tr><td>上下文裁剪</td><td>prefill 成本</td><td>证据召回与中间迷失</td></tr><tr><td>模型路由</td><td>平均成本</td><td>错误下放与级联尾延迟</td></tr></tbody></table></div><p>一次只改变少量变量并保留逐请求版本，才能知道收益来自哪里；把五种优化一起上线会失去归因。</p><p>优化选择输入当前瓶颈、批处理参数、缓存键、量化位宽、上下文和路由策略，输出吞吐、首 token 延迟、显存、质量与隔离差异。批处理改变排队，缓存复用计算，量化改变数值表示，裁剪改变可见证据，路由改变请求模型；它们的风险并不相同。一次只改少量变量并记录逐请求版本，才能归因和回归。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>影子、金丝雀、蓝绿解决不同风险<span class=\"dd-badge eng\">发布</span></h2><p class=\"dd-lead\">既然都有“先别全量”的含义，为什么需要三种策略？</p><ol class=\"dd-steps\"><li><b>离线门禁：</b>冻结集排除已知质量、安全和契约回归。</li><li><b>影子：</b>复制真实输入给候选但不影响用户；验证容量、分布和读操作，禁止真实不可逆副作用。</li><li><b>金丝雀：</b>稳定用户单位接受真实结果，逐级 1%→5%→25%→100%，每级观察完整标签窗口。</li><li><b>蓝绿：</b>保留两套完整环境，用流量切换快速回退，代价是双份容量和状态同步。</li></ol><p>影子无法测用户后续行为，金丝雀会真实造成伤害，蓝绿也不能自动回退外部工具已执行的退款。发布策略必须与副作用隔离、幂等和补偿共同设计。</p><div class=\"dd-note warn\"><b>分流单位：</b>不要按单次请求随机导致同一会话跨版本；按用户/会话稳定哈希，并排除员工、机器人或地区比例失衡。</div><p>发布策略输入候选版本、真实流量、副作用风险、观察窗口和回滚能力，输出影子、金丝雀、蓝绿及分级流量动作。影子结果不影响用户且禁止不可逆动作，金丝雀产生真实结果，蓝绿保留两套完整环境；策略选择取决于要观察的风险。按用户或会话稳定分流，任何副作用都需要幂等和补偿。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>回滚需要原子版本和向后兼容<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">把模型退回 v41，为什么系统仍可能继续答错？</p><p>因为提示已变、索引已重建、工具 schema 已迁移、缓存仍装着 v42 前缀，或数据库写入不可逆。发布清单要给组合版本一个 release id，记录依赖兼容矩阵；回滚要同时恢复可回滚组件并明确不能逆转的状态。</p><p>数据库和工具动作使用幂等键，重试不重复退款；schema 变更采用 expand/contract，先让新旧代码都能读写，再迁移，最后删除旧字段。索引可蓝绿构建并原子切别名，缓存键包含 release id。事故演练要实际验证回滚时长，而不是相信文档。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"发布单元的组成\"><mi>ReleaseUnit</mi><mo>=</mo><mo>{</mo><mi>Model</mi><mo>,</mo><mi>Prompt</mi><mo>,</mo><mi>Decode</mi><mo>,</mo><mi>Index</mi><mo>,</mo><mi>ToolSchema</mi><mo>,</mo><mi>Policy</mi><mo>,</mo><mi>Code</mi><mo>,</mo><mi>Infra</mi><mo>}</mo></math></div><p>原子发布输入模型、提示、解码、索引、工具 schema、策略、代码和基础设施配置，输出一个 releaseId 与兼容矩阵。回滚按 releaseId 同步恢复可逆组件，数据库工具使用幂等键和 expand/contract schema，索引用蓝绿别名；单退模型会留下新提示、缓存或状态。不可逆副作用只能补偿，不能假装已经回滚。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>容量不足时怎样安全降级<span class=\"dd-badge eng\">降级</span></h2><p class=\"dd-lead\">峰值超过容量时，是排队、拒绝、缩短输出还是切小模型？</p><p>按风险和任务价值分层：低风险摘要可切小模型或延迟；高权限退款不能因拥塞跳过验证。设置输入/输出上限、优先级队列、背压、超时、有限重试和熔断；为关键路径保留容量。</p><p>降级本身是产品行为，要在评测集中覆盖。小模型可能使更多请求升级，先小后大反而加重峰值；缓存陈旧会返回旧政策；截短输出可能丢失警告。所有降级响应应显式标记并可观测，恢复后避免瞬间重放积压造成第二次雪崩。</p><div class=\"dd-note warn\"><b>重试风暴：</b>超时不代表上游停止计算或工具未执行。只有可恢复错误才重试，并使用抖动退避、总预算与同一幂等键。</div><p>安全降级输入容量、风险等级、任务价值、可逆性和当前依赖状态，输出排队、拒绝、延迟、小模型、截短或停服动作。低风险任务可延迟或切换模型，高权限退款不得因拥塞绕过验证；每个降级结果都要显式标记并监控。超时不证明上游停止或工具未执行，重试必须有可恢复条件、总预算和同一幂等键。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">部署质量由最弱的生产约束决定，而不是由离线模型分数单独决定。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>端侧一定更快更私密</td><td>受设备性能、更新和本地数据暴露影响</td></tr><tr><td>吞吐高代表体验好</td><td>大批处理可提高吞吐却恶化排队与尾延迟</td></tr><tr><td>影子通过就可全量</td><td>它不测真实交互和不可逆副作用</td></tr><tr><td>回滚模型即可恢复</td><td>提示、索引、工具、缓存和状态都属于发布单元</td></tr><tr><td>拥塞时多重试</td><td>会放大负载和重复副作用，需背压与幂等</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>模型选型、应用评测、推理优化、分布式系统</td></tr><tr><td><b>本页核心</b></td><td>运行位置、容量、尾延迟、渐进发布、原子版本、降级回滚</td></tr><tr><td>在线闭环</td><td>可观测性、数据漂移、模型路由、不确定性校准</td></tr><tr><td>安全延伸</td><td>身份权限、工作流幂等、隐私和事件响应</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义位置/隐私/延迟/容量约束</li><li>把全部依赖冻结成发布单元</li><li>离线评测并压力测试</li><li>影子验证真实分布与容量</li><li>金丝雀按门槛渐进放量</li><li>告警时降级/回滚并回流失败</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>利用率接近 1 时为什么危险？</li><li>影子与金丝雀最关键差别？</li><li>为什么模型回滚可能不完整？</li><li>无条件重试为何会雪崩？</li><li>量化上线要回归什么？</li><li>假设“AI 部署：把离线能力变成可容量化、可灰度、可回滚的服务”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>随机到达会使排队和尾延迟非线性上升，平均服务时间仍可很低。</li><li>影子结果不影响用户且不应执行真实副作用；金丝雀会真实生效。</li><li>提示、索引、工具 schema、缓存和状态可能仍属于新版本。</li><li>超时工作可能仍占资源，重试增加负载并可能重复副作用。</li><li>不仅吞吐显存，还要关键切片质量、长上下文和校准。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://papers.nips.cc/paper/5656-hidden-technical-debt-in-machine-learning-systems\" target=\"_blank\" rel=\"noopener\">Hidden Technical Debt in Machine Learning Systems</a>：ML 系统组合依赖与运维债务</li><li><a href=\"https://sre.google/sre-book/handling-overload/\" target=\"_blank\" rel=\"noopener\">Google SRE Book: Handling Overload</a>：容量、背压、降级与负载保护</li><li><a href=\"https://docs.aws.amazon.com/prescriptive-guidance/latest/mlops-checklist/continuous-deployment.html\" target=\"_blank\" rel=\"noopener\">AWS MLOps Continuous Deployment</a>：影子、金丝雀、蓝绿与回滚</li><li><a href=\"https://airc.nist.gov/airmf-resources/airmf/5-sec-core/\" target=\"_blank\" rel=\"noopener\">NIST AI RMF Core</a>：部署监测、事件响应和变更管理</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
